In this script, I use a random URL for demonstration purposes. In a real-world scenario, you would probably want to use a service like ngrok to create a public URL for your local development server.

Please note that you need to have Flask installed in your Python environment to run this script. You can install Flask using pip:

`pip install flask`

Here is the script:

```python
from flask import Flask, request, jsonify
import random
import string

app = Flask(__name__)

# Dictionary to store the links
links = {}

@app.route('/screenshare', methods=['POST'])
def generate_link():
    if request.method == 'POST':
        url = request.json.get('url')
        if url:
            # Generate a random link
            random_string = ''.join(random.choices(string.ascii_letters + string.digits, k=10))
            link = f'http://example.com/{random_string}'
            links[random_string] = url
            return jsonify({'link': link})
        else:
            return jsonify({'error': 'No URL provided'}), 400
    else:
        return jsonify({'error': 'Invalid request method'}), 405

@app.route('/<string:random_string>')
def share(random_string):
    if random_string in links:
        return jsonify({'url': links[random_string]})
    else:
        return jsonify({'error': 'Invalid link'}), 404

if __name__ == '__main__':
    app.run(debug=True)
```

