import React, { useContext } from 'react';
import { FeedbackContext } from './FeedbackContext';

const Form = () => {
  const { forms, handleFeedback } = useContext(FeedbackContext);
  const [feedback, setFeedback] = useState({});

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFeedback({ ...feedback, [name]: value });
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    handleFeedback(feedback);
    setFeedback({}); // Reset feedback
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>{forms.title}</h2>
      {forms.questions.map((question) => (
        <div key={question.id}>
          <label>{question.question}</label>
          {question.options && (
            <select name={question.id} onChange={handleInputChange}>
              {question.options.map((option) => (
                <option key={option}>{option}</option>
              ))}
            </select>
          )}
          {question.question !== 'How would you rate the instructor?' && (
            <textarea name={question.id} onChange={handleInputChange} />
          )}
        </div>
      ))}
      <button type="submit">Submit</button>
    </form>
  );
};

export default Form;
```
