          angularVelocity += (-angularVelocity * 队.cancel) + (g * Math.sin(angle));
          angle += angularVelocity;
        }
        draw();
      }

      function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.lineWidth = 2;
        ctx.strokeStyle = 'black';
        ctx.moveTo(canvas.width / 2, canvas.height / 2);
        ctx.lineTo(canvas.width / 2 + Math.sin(angle) * 50, canvas.height / 2 - Math.cos(angle) * 50);
        ctx.stroke();
        requestAnimationFrame(update);
