Here is an AWS Lambda function in Go that deletes EBS Snapshots based on the specified tag and retention rules:
```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS Snapshots with the "backup_type" tag
	input := &ec2.DescribeSnapshotsInput{
		Filter: []*ec2.Filter{
			{
				Name:   aws.String("tag:backup_type"),
			 Values: []*string{},
			},
		},
	}
	snapshots, err := ec2Svc.DescribeSnapshots(input)
	if err != nil {
		return nil, err
	}

	// Process each snapshot
	for _, snapshot := range snapshots.Snapshots {
		tagVal, ok := getTagValue(*snapshot.Tags, "backup_type")
		if !ok {
			continue
		}

		// Determine retention rule based on tag value
		var retention int64
		switch tagVal {
		case "monthly":
			retention = int64(14)
		case "daily":
			retention = int64(10)
		case "weekly":
			retention = int64(4)
		case "yearly":
			retention = int64(1)
		default:
			continue
		}

		// Get the snapshot's creation date
		date, err := getSnapshotCreateDate(snapshot)
		if err != nil {
			return nil, err
		}

		// Delete the snapshot if it's older than the retention rule
		if int64(len(snapshots.Snapshots)) > retention {
			if date.Before(GetRetentionDate(retention)) {
				_, err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
				if err != nil {
					return nil, err
				}
			}
		}
	}

	return nil, nil
}

func getTagValue(tags []*ec2.Tag, key string) (string, bool) {
	for _, tag := range tags {
		if *tag.Key == key {
			return *tag.Value, true
		}
	}
	return "", false
}

func getSnapshotCreateDate(snapshot *ec2.Snapshot) (time.Time, error) {
	createdAt, err := time.Parse(time.RFC3339, *snapshot.CreationDate)
	if err != nil {
		return time.Time{}, err
	}
	return createdAt, nil
}

func GetRetentionDate(retention int64) time.Time {
	date := time.Now().AddDate(0, 0, -int(-retention))
	return date
}

func main() {
	lambda.Start(handler)
}
```
This code uses the `ec2` SDK to get all EBS Snapshots with the "backup_type" tag, and then processes each snapshot to determine if it should be deleted based on the retention rule.

The retention rule is as follows:

* Monthly snapshots: keep the last 14 snapshots
* Daily snapshots: keep the last 10 snapshots
* Weekly snapshots: keep the last 4 snapshots
* Yearly snapshots: keep only the most recent snapshot

The code uses the `getTagValue` function to extract the "backup_type" tag value from each snapshot, and then uses a switch statement to determine the retention rule based on the tag value.

The `getSnapshotCreateDate` function is used to extract the snapshot's creation date from its `CreationDate` attribute, and the `GetRetentionDate` function is used to calculate the date that is `retention` days old from the current date.

Finally, the code uses the `DeleteSnapshot` method to delete the snapshot if it's older than the retention rule.

